def transform(grid):
    h,w=len(grid),len(grid[0]); g=[r[:] for r in grid]; bg=grid[1][0]
    # singleton marker color is the unique color not used by background or edge bars
    counts={}
    for row in grid:
        for x in row: counts[x]=counts.get(x,0)+1
    marker=next(x for x,n in counts.items() if x!=bg and n<min(h,w))
    for r in range(h):
        for c in range(w):
            if grid[r][c]==marker:
                g[r][c]=4
                if r < h-1-r:
                    for rr in range(r-1,-1,-1):
                        if grid[rr][c]==bg: g[rr][c]=marker
                else:
                    for rr in range(r+1,h):
                        if grid[rr][c]==bg: g[rr][c]=marker
    return g

